arguments.file_text:
namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public required string Title { get; set; }
    public required string Category { get; set; }
    public required string Description { get; set; }
    public required List<string> Ingredients { get; set; }
    public required List<string> Steps { get; set; }
    public string ImageUrl { get; set; } = string.Empty;
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public required string Name { get; set; }
    public required string Slug { get; set; }
    public required string Description { get; set; }
    public required string Icon { get; set; }
    public int RecipeCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories;
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _categories =
        [
            new RecipeCategory { Name = "Breakfast", Slug = "breakfast", Description = "Start your day right with hearty breakfast recipes", Icon = "🥞" },
            new RecipeCategory { Name = "Lunch", Slug = "lunch", Description = "Quick and satisfying midday meals", Icon = "🥗" },
            new RecipeCategory { Name = "Dinner", Slug = "dinner", Description = "Delicious dinner recipes for the whole family", Icon = "🍝" },
            new RecipeCategory { Name = "Desserts", Slug = "desserts", Description = "Sweet treats and indulgent desserts", Icon = "🍰" },
            new RecipeCategory { Name = "Snacks", Slug = "snacks", Description = "Easy bites for any time of day", Icon = "🍿" },
            new RecipeCategory { Name = "Drinks", Slug = "drinks", Description = "Refreshing beverages and cocktails", Icon = "🥤" },
        ];

        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Pancakes", Category = "breakfast",
                Description = "Fluffy golden pancakes perfect for a weekend morning.",
                Ingredients = ["2 cups all-purpose flour", "2 tbsp sugar", "2 tsp baking powder", "1 tsp salt", "2 eggs", "1¾ cups milk", "¼ cup melted butter"],
                Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Heat a griddle over medium heat and grease lightly.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown. Serve with maple syrup."],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Avocado Toast", Category = "breakfast",
                Description = "Simple, healthy, and endlessly customizable avocado toast.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper to taste", "Red pepper flakes", "1 egg (optional)"],
                Steps = ["Toast the bread until golden and crisp.", "Mash avocado with lemon juice, salt, and pepper.", "Spread avocado mixture on toast.", "Top with red pepper flakes and a fried egg if desired."],
                TotalRatings = 8, RatingSum = 35
            },
            new Recipe
            {
                Id = 3, Title = "Caesar Salad", Category = "lunch",
                Description = "A crisp, tangy Caesar salad with homemade dressing.",
                Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "2 tbsp olive oil", "1 tbsp lemon juice", "1 tsp Dijon mustard", "1 garlic clove, minced", "1 anchovy fillet (optional)"],
                Steps = ["Wash and chop romaine lettuce.", "Whisk olive oil, lemon juice, mustard, garlic, and anchovy into a dressing.", "Toss lettuce with dressing.", "Top with croutons and shaved parmesan."],
                TotalRatings = 6, RatingSum = 25
            },
            new Recipe
            {
                Id = 4, Title = "Grilled Chicken Wrap", Category = "lunch",
                Description = "A protein-packed wrap with grilled chicken and fresh veggies.",
                Ingredients = ["2 chicken breasts", "2 large flour tortillas", "1 cup mixed greens", "½ cup diced tomatoes", "¼ cup ranch dressing", "Salt and pepper"],
                Steps = ["Season chicken with salt and pepper, grill until cooked through.", "Slice chicken into strips.", "Lay tortillas flat and layer greens, tomatoes, and chicken.", "Drizzle with ranch dressing.", "Roll tightly and slice in half."],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 5, Title = "Spaghetti Bolognese", Category = "dinner",
                Description = "Rich and meaty Bolognese sauce over perfectly cooked pasta.",
                Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "2 garlic cloves, minced", "400g crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper", "Fresh basil"],
                Steps = ["Cook spaghetti according to package directions.", "Brown ground beef in a large pan, drain excess fat.", "Sauté onion and garlic until soft.", "Add crushed tomatoes, tomato paste, and oregano.", "Simmer for 20 minutes, season to taste.", "Serve sauce over spaghetti, garnish with fresh basil."],
                TotalRatings = 15, RatingSum = 68
            },
            new Recipe
            {
                Id = 6, Title = "Chicken Stir-Fry", Category = "dinner",
                Description = "A quick and colorful chicken stir-fry with vegetables.",
                Ingredients = ["2 chicken breasts, sliced", "1 bell pepper, sliced", "1 cup broccoli florets", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 garlic cloves, minced", "1 tsp ginger, grated"],
                Steps = ["Mix soy sauce, sesame oil, and cornstarch for the sauce.", "Heat oil in a wok over high heat.", "Stir-fry chicken until golden, remove and set aside.", "Stir-fry vegetables with garlic and ginger for 3 minutes.", "Return chicken to wok, pour sauce over everything.", "Toss until sauce thickens. Serve over rice."],
                TotalRatings = 9, RatingSum = 39
            },
            new Recipe
            {
                Id = 7, Title = "Chocolate Lava Cake", Category = "desserts",
                Description = "Decadent individual chocolate cakes with a molten center.",
                Ingredients = ["200g dark chocolate", "100g butter", "3 eggs", "3 egg yolks", "⅓ cup sugar", "2 tbsp flour", "Cocoa powder for dusting"],
                Steps = ["Preheat oven to 425°F (220°C).", "Melt chocolate and butter together.", "Whisk eggs, egg yolks, and sugar until thick.", "Fold chocolate mixture into egg mixture.", "Add flour and mix gently.", "Pour into greased ramekins, bake 12-14 minutes.", "Invert onto plates and serve immediately."],
                TotalRatings = 20, RatingSum = 95
            },
            new Recipe
            {
