@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit a Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Recipe submitted!</h4>
        <p>Your recipe "<strong>@model.Title</strong>" has been added. <a href="/category/@model.Category">View it in its category</a>.</p>
        <button class="btn btn-outline-success" @onclick="Reset">Submit another</button>
    </div>
}
else
{
    <div class="card shadow-sm">
        <div class="card-body">
            <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label for="title" class="form-label fw-bold">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label fw-bold">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                        <option value="">— Select a category —</option>
                        @foreach (var cat in RecipeService.GetCategories())
                        {
                            <option value="@cat.Slug">@cat.Icon @cat.Name</option>
                        }
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="description" class="form-label fw-bold">Short Description</label>
                    <InputText id="description" class="form-control" @bind-Value="model.Description" placeholder="A brief summary of the recipe" />
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label fw-bold">Ingredients</label>
                    <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="model.Ingredients" placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                    <div class="form-text">Enter one ingredient per line.</div>
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label fw-bold">Steps</label>
                    <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="model.Steps" placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
                    <div class="form-text">Enter one step per line.</div>
                </div>

                <div class="d-flex gap-2">
                    <button type="submit" class="btn btn-success"
                            disabled="@(!IsValid)">
                        Submit Recipe
                    </button>
                    <a href="/" class="btn btn-outline-secondary">Cancel</a>
                </div>
            </EditForm>
        </div>
    </div>
}

@code {
    private RecipeSubmission model = new();
    private bool submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(model.Title) &&
        !string.IsNullOrWhiteSpace(model.Category) &&
        !string.IsNullOrWhiteSpace(model.Ingredients) &&
        !string.IsNullOrWhiteSpace(model.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        RecipeService.AddRecipe(model);
        submitted = true;
    }

    private void Reset()
    {
        model = new();
        submitted = false;
    }
}
