@page "/category/{Slug}"
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>@(category?.Name ?? "Category") — RecipeHub</PageTitle>

@if (category is null)
{
    <h1>Category not found</h1>
    <p>Sorry, we couldn't find that category. <a href="/">Browse all categories</a>.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@category.Name</li>
        </ol>
    </nav>

    <h1>@category.Icon @category.Name</h1>
    <p class="lead text-muted">@category.Description</p>

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">
            No recipes in this category yet. <a href="/submit">Be the first to submit one!</a>
        </div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
            @foreach (var recipe in recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text text-muted">@recipe.Description</p>
                            <div class="d-flex justify-content-between align-items-center">
                                <span class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                    }
                                    <small class="text-muted ms-1">(@recipe.TotalRatings)</small>
                                </span>
                                <a href="/recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter] public string Slug { get; set; } = string.Empty;

    private RecipeCategory? category;
    private List<Recipe> recipes = [];

    protected override void OnInitialized()
    {
        category = RecipeService.GetCategoryBySlug(Slug);
        if (category is not null)
        {
            recipes = RecipeService.GetRecipesByCategory(Slug);
        }
    }
}

